{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목에 맞는 개선 방법을 선택할 수 있는지 확인한다. 실행 계획과 조회 조건을 인덱스 추가 판단에 어떻게 연결했는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 운영 화면의 신고 목록 조회 쿼리가 느려 실행 계획을 살펴봤다.",
          "task": "조회 조건에 맞는 인덱스를 추가하고 조인 순서를 정리했다.",
          "action": "실행 계획과 조회 조건에서 어떤 정보를 근거로 인덱스 추가를 선택했는지 설명한다.",
          "result": "선택한 인덱스가 당시 조회 쿼리의 병목을 줄이는 데 적합하다고 판단한 이유를 설명한다."
        },
        "expectedEvidence": [
          "조회 조건에 맞는 인덱스를 추가하기로 판단한 근거",
          "인덱스 추가 판단을 뒷받침한 실행 계획의 관찰 내용",
          "조회 조건과 선택한 인덱스 사이의 관계"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리의 실행 계획을 살펴보셨을 때, 조회 조건에 맞는 인덱스를 추가한 근거는 무엇이었나요?",
      "answerTip": "핵심부터 말하고 구체적으로 덧붙여 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 관찰한 조회 부담을 구체적으로 짚어 인덱스 추가의 근거로 제시한다.",
            "조회 조건과 선택한 인덱스의 관계를 설명하며 해당 인덱스가 병목에 적합한 이유를 타당하게 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "조회 속도를 개선하려고 인덱스를 추가했다고 답하지만 실행 계획에서 확인한 근거가 포괄적이다.",
            "조회 조건과 인덱스의 관련성을 설명하지만 해당 선택이 병목을 줄이는 이유는 일부만 뒷받침한다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스를 추가했다는 사실이나 개선 수치만 반복하고 선택 근거를 제시하지 못한다.",
            "실행 계획이나 조회 조건과 무관한 일반론을 제시하거나 인덱스의 작동 원리를 잘못 이해한 근거를 든다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 확인한 장애 원인을 재발 방지 판단에 연결할 수 있는지 확인한다. 스케줄러 중복 실행을 배포 체크리스트의 점검 대상으로 삼은 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 알림 중복 발송 로그를 시간순으로 보고 스케줄러가 서버 두 대에서 동시에 실행되고 있음을 찾았다.",
          "task": "배포 체크리스트에 스케줄러 항목을 넣었다.",
          "action": "스케줄러를 재발 방지용 배포 체크리스트에 넣어야 한다고 판단한 근거를 설명한다.",
          "result": "체크리스트의 스케줄러 항목이 확인된 장애 원인의 반복을 막는 데 어떤 의미가 있는지 설명한다."
        },
        "expectedEvidence": [
          "스케줄러를 재발 방지용 배포 체크리스트에 넣은 판단 근거",
          "그 판단을 뒷받침한 스케줄러 중복 실행의 로그 내용",
          "스케줄러 점검과 같은 장애의 재발 방지 사이의 관계"
        ]
      },
      "question": "포켓마켓에서 알림 중복 발송 로그를 시간순으로 보셨을 때, 재발 방지용 배포 체크리스트에 스케줄러를 넣은 근거는 무엇이었나요?",
      "answerTip": "핵심부터 말하고 구체적으로 덧붙여 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "로그에서 확인한 스케줄러 중복 실행을 체크리스트에 스케줄러를 넣은 구체적인 근거로 제시한다.",
            "스케줄러 점검이 동일한 장애 원인의 반복을 막는 데 필요한 이유를 설명하며 재발 방지 판단을 타당하게 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "같은 장애를 막으려고 스케줄러를 체크리스트에 넣었다고 답하지만 로그와 연결한 근거가 포괄적이다.",
            "체크리스트에 스케줄러를 포함할 필요성은 설명하지만 확인된 장애 원인과 재발 방지의 관계는 일부만 뒷받침한다."
          ]
        },
        "poor": {
          "criteria": [
            "체크리스트에 항목을 넣었다는 사실만 반복하고 스케줄러를 포함한 근거를 제시하지 못한다.",
            "잠금으로 오류를 수정한 내용이나 일반적인 배포 주의사항만 말하고 체크리스트에 스케줄러를 넣은 판단에는 답하지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업·사용자 요청을 요구사항으로 구체화할 때 구현 범위를 판단할 수 있는지 확인한다. 인터뷰에서 얻은 요청이 개발 담당 팀원과 요구사항 범위를 조정한 판단에 어떻게 연결됐는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳 인터뷰로 요구사항 정의서를 작성했다.",
          "task": "기획 담당으로 개발 담당 팀원과 범위를 조정했다.",
          "action": "요구사항 범위를 조정한 근거를 당시의 요청과 연결해 설명한다.",
          "result": "제시한 근거가 요구사항 범위를 조정할 타당한 이유가 되는지 설명한다."
        },
        "expectedEvidence": [
          "요구사항 범위를 조정한 구체적인 판단 근거",
          "범위 판단을 뒷받침한 요청의 목적이나 필요성",
          "당시 요구사항 범위 판단에 영향을 준 제약이나 조건"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳 인터뷰로 요구사항 정의서를 작성하셨을 때, 요구사항 범위를 조정한 근거는 무엇이었나요?",
      "answerTip": "한 가지 사례를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "요구사항 범위를 조정한 근거를 당시 요청의 목적이나 필요성과 연결해 구체적으로 설명한다.",
            "제시한 근거가 해당 요구사항을 범위에 포함하거나 제외할 이유로 타당하며, 당시 조건과도 일치한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요구사항 범위를 조정한 근거를 제시하지만 요청의 목적이나 필요성과의 연결이 일반적이다.",
            "범위 판단의 방향은 타당하지만 당시 조건을 뒷받침하는 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항 정의서를 작성했다는 사실만 반복하고 범위를 조정한 근거를 제시하지 못한다.",
            "문서 작성 도구나 협업의 중요성만 설명해 요구사항 범위 판단에서 벗어난다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능의 예외 상황을 화면설계에 구체화할 수 있는지 확인한다. 예약·취소·알림 흐름에서 어떤 예외 상황을 화면에 반영해야 한다고 판단했는지 그 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 Figma로 작성했다.",
          "task": "기획 담당으로 예약·취소·알림의 기능 흐름과 예외 상황을 화면설계서에 담았다.",
          "action": "예외 상황을 화면에 반영한 근거를 해당 기능의 흐름이나 화면 상태 차이와 연결해 설명한다.",
          "result": "선택한 예외 상황이 화면설계에 필요한 이유가 답변에서 드러난다."
        },
        "expectedEvidence": [
          "예외 상황을 화면에 반영한 구체적인 판단 근거",
          "그 판단을 뒷받침한 기능 흐름이나 화면 상태의 차이"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 화면설계서를 작성하셨을 때, 예외 상황을 화면에 반영한 근거는 무엇이었나요?",
      "answerTip": "당시 경험을 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황을 화면에 반영한 근거를 실제 설계한 기능 흐름이나 화면 상태와 연결해 구체적으로 설명한다.",
            "그 근거가 정상 흐름만으로 다루기 어려운 화면상의 차이를 설명하며, 예외 상황을 설계에 포함할 이유로 타당하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황을 화면에 반영한 근거를 제시하지만 기능 흐름이나 화면 상태와의 연결이 구체적이지 않다.",
            "예외 상황을 포함할 이유는 타당하지만 해당 화면에서 필요한 이유를 뒷받침하는 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "화면설계서에 예외 상황을 넣었다는 사실만 반복하고 판단 근거를 제시하지 못한다.",
            "Figma 기능이나 화면 수만 설명해 예외 상황을 화면에 반영한 판단에서 벗어난다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 그대로 수행하지 않고 투약을 멈출 수 있는지 평가한다. 평소와 다른 처방 용량을 투약 중단이 필요한 신호로 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 근무 중 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어왔다.",
          "task": "지원자는 투약 전에 용량이 이상하다고 느껴 투약을 멈추고 담당의에게 확인했다.",
          "action": "당시 처방 용량의 차이를 투약 중단이 필요한 문제로 판단한 근거를 설명한다.",
          "result": "답변에서 처방의 정확성을 확신할 수 없는 상태에서 투약을 진행하지 않은 판단의 타당성이 드러난다."
        },
        "expectedEvidence": [
          "투약을 멈추기로 판단한 구체적인 근거",
          "당시 처방 용량과 평소 용량의 차이",
          "그 차이를 투약 전 해소해야 할 불확실성으로 본 이유"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배였을 때, 투약을 멈추기로 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 경험을 본인의 말로 간결하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방 용량이 평소의 두 배였다는 구체적인 차이를 투약 중단 판단과 연결해 설명한다.",
            "용량 차이만으로 오류를 단정하지 않으면서도 처방의 정확성이 불확실한 상태에서 투약을 진행할 수 없었던 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "용량이 평소와 달라 투약을 멈췄다고 답하지만 당시 판단의 근거가 구체적이지 않다.",
            "의심스러운 처방은 확인 전 투약하지 않아야 한다고 설명하지만 해당 용량 차이와의 연결은 제한적이다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 판단의 근거 대신 입력 오류였다는 사후 결과만 반복한다.",
            "처방 용량의 차이를 검토할 필요가 없다고 하거나 투약 중단과 무관한 일반론으로 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태에 관한 정보를 다음 근무자 인수인계로 연결하는 판단을 평가한다. 진통제 투여 시각과 보행 보조 여부를 인수인계 항목으로 제안한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "낙상 고위험 환자 인수인계 체크리스트 개선 활동에서 사고 보고서를 통해 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰린다는 점을 확인했다.",
          "task": "지원자는 인수인계 체크리스트에 진통제 투여 시각과 보행 보조 여부를 넣자고 제안했다.",
          "action": "진통제 투여 시각과 보행 보조 여부를 인수인계 항목으로 고른 근거를 설명한다.",
          "result": "답변에서 두 항목이 다음 근무자의 환자 상태 파악에 필요한 정보라는 판단이 드러난다."
        },
        "expectedEvidence": [
          "진통제 투여 시각과 보행 보조 여부를 인수인계 항목으로 제안한 근거",
          "두 항목과 환자의 보행 중 낙상 위험 사이의 관련성",
